// @vitest-environment node
/**
 * The placeholder practice-schedule fixture (`fixtures/practice-schedule-2026/`, generated by
 * `scripts/build-practice-fixture.mjs`; plan `docs/changes/2026-11-03-schedule-expansion.md`
 * section 4.11.7, PR 9 task J1).
 *
 * What this holds, and what it does NOT take from anywhere:
 *
 *   - **The files are the generator's output.** A checked-in file that differs from a fresh build
 *     fails, and the script's own `--check` is run for real, on the real directory (exit 0), on a copy
 *     with one cell changed (exit 1, naming the file) and on a copy missing a file (exit 1).
 *   - **The shape** (counts only, near the shape of the owner's practice workbook, plan 4.11.1): the
 *     produced numbers are pinned here and in the README. Every value in every file is invented;
 *     nothing was taken from the owner's workbook, which this repository has never held.
 *   - **Placeholders only**: every cell has the shape of an invented name; no `@` anywhere.
 *     (`tests/realNameDenylist.test.js` scans `fixtures/` as well.)
 *   - **The plants are counted from the CSV, not from the generator.** `tests/helpers/practiceSweep.js`
 *     (plain loops; it imports neither the generator nor the product) recounts every plant from the
 *     rows, with the roster (`teams.csv`, `divisions.csv`) as the subject set. The generator's own
 *     record is the second count; they must agree. The pre-plant copy (`plants: false`) is the control:
 *     the same sweep finds nothing there. The sweep itself is shown able to fail on small hand-made
 *     files (a check that examined nothing is a failure, not a pass).
 *
 * Statically out of reach, and so not claimed: that the shape is the same shape as the owner's
 * workbook beyond the counts the plan lists, and that `practice-invalid.csv` is judged as the importer
 * will judge it. That second half is `tests/practiceImportParse.test.js`, which reads the expectation
 * each row carries in `Notes`.
 */

import { spawnSync } from 'node:child_process';
import { cpSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import Papa from 'papaparse';
import { afterAll, describe, expect, it } from 'vitest';
import { coachTeams, countPlants, shapeOf } from './helpers/practiceSweep.js';
import {
  PRACTICE_FIXTURE_DIR,
  PRACTICE_FIXTURE_FILES,
  PRACTICE_PLANT_COUNTS,
  buildPracticeFixture,
  fixtureDifferences,
} from '../scripts/build-practice-fixture.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SCRIPT = path.join(HERE, '..', 'scripts', 'build-practice-fixture.mjs');

const scratch = mkdtempSync(path.join(tmpdir(), 'practice-fixture-'));
afterAll(() => rmSync(scratch, { recursive: true, force: true }));

/** @param {string} text */
function parseCsv(text) {
  const { data, meta, errors } = Papa.parse(text, { header: true, skipEmptyLines: true });
  expect(errors).toEqual([]);
  return { rows: /** @type {Record<string, string>[]} */ (data), fields: meta.fields ?? [] };
}
/** @param {string} file */
const onDisk = (file) => parseCsv(readFileSync(path.join(PRACTICE_FIXTURE_DIR, file), 'utf8'));

const SCHEDULE = onDisk('practice-schedule.csv');
const TEAMS = onDisk('teams.csv');
const DIVISIONS = onDisk('divisions.csv');
const SURFACES = onDisk('surfaces.csv');
const ALIASES = onDisk('aliases.csv');
const INVALID = onDisk('practice-invalid.csv');

const SCHEDULE_HEADERS = [
  'Team',
  'Division',
  'Day',
  'Start',
  'End',
  'Location',
  'Field',
  'Subunit',
  'Valid From',
  'Valid Until',
  'Capacity',
  'Use',
  'Block',
];

/** The produced shape, pinned. The plan's targets (4.11.1) are beside each as a comment. */
const SHAPE = {
  rows: 710, // 726 timed cells in the grid; a whole-field placement is one row, not two
  open: 473,
  venues: 8, // 8
  fields: 29,
  labelledRows: 58, // 58 (16 + 42)
  usedLabelledRows: 49, // 49
  singlePractice: 29, // 29
  twoPractice: 103, // 103
  twoWeekday: 98, // 98
  sameWeekday: 5, // 5
  sameSlotBothDays: 83, // 83
  wholeFieldPlacements: 20, // about 20
  patterns: { 'Tue+Thu': 49, 'Mon+Wed': 38, 'Wed+Fri': 8, 'Mon+Thu': 3 },
  placements: 236, // about 235
  placements45: 37, // about 37
  placements60: 199, // about 198
  holds: 1, // 1 (a non-team activity)
};

/* -------------------------------------------------------------------------- */

describe('practice fixture: the files are the generator output', () => {
  const built = buildPracticeFixture();

  it('holds exactly the generated files, byte for byte', () => {
    expect(Object.keys(built.files).sort()).toEqual([...PRACTICE_FIXTURE_FILES].sort());
    for (const file of PRACTICE_FIXTURE_FILES) {
      expect(readFileSync(path.join(PRACTICE_FIXTURE_DIR, file), 'utf8')).toBe(built.files[file]);
    }
    expect(fixtureDifferences()).toEqual([]);
  });

  it('keeps a README beside them', () => {
    const names = readdirSync(PRACTICE_FIXTURE_DIR);
    expect(names).toContain('README.md');
    expect(names.filter((n) => n !== 'README.md').sort()).toEqual(
      [...PRACTICE_FIXTURE_FILES].sort()
    );
  });

  it('is deterministic, and does not read the host time zone', () => {
    const original = process.env.TZ;
    try {
      process.env.TZ = 'Pacific/Auckland';
      const auckland = buildPracticeFixture();
      process.env.TZ = 'America/New_York';
      const newYork = buildPracticeFixture();
      expect(auckland.files).toEqual(built.files);
      expect(newYork.files).toEqual(built.files);
    } finally {
      if (original === undefined) delete process.env.TZ;
      else process.env.TZ = original;
    }
  });

  it('--check exits 0 on the real directory', () => {
    const run = spawnSync(process.execPath, [SCRIPT, '--check'], { encoding: 'utf8' });
    expect(run.status).toBe(0);
  });

  it('--check exits 1 on a copy with one cell changed, and names the file', () => {
    const copy = path.join(scratch, 'one-cell');
    cpSync(PRACTICE_FIXTURE_DIR, copy, { recursive: true });
    const control = spawnSync(process.execPath, [SCRIPT, '--check', '--dir', copy], {
      encoding: 'utf8',
    });
    expect(control.status).toBe(0); // the copy is clean first, so the failure below is the edit's
    const text = readFileSync(path.join(copy, 'practice-schedule.csv'), 'utf8');
    writeFileSync(path.join(copy, 'practice-schedule.csv'), text.replace('Venue A', 'Venue Z'));
    const run = spawnSync(process.execPath, [SCRIPT, '--check', '--dir', copy], {
      encoding: 'utf8',
    });
    expect(run.status).toBe(1);
    expect(run.stderr).toContain('practice-schedule.csv');
  });

  it('--check exits 1 on a copy missing a file', () => {
    const copy = path.join(scratch, 'missing');
    cpSync(PRACTICE_FIXTURE_DIR, copy, { recursive: true });
    rmSync(path.join(copy, 'aliases.csv'));
    const run = spawnSync(process.execPath, [SCRIPT, '--check', '--dir', copy], {
      encoding: 'utf8',
    });
    expect(run.status).toBe(1);
    expect(run.stderr).toContain('aliases.csv');
  });
});

describe('practice fixture: every cell is a placeholder', () => {
  it('has the import format of plan 4.11.2 plus a column the importer drops', () => {
    expect(SCHEDULE.fields).toEqual(SCHEDULE_HEADERS);
    expect(TEAMS.fields).toEqual(['Team', 'Division', 'Coach 1', 'Coach 2', 'Coach 3']);
    expect(DIVISIONS.fields).toEqual(['Division', 'Practices Per Week', 'Practice Minutes']);
    expect(SURFACES.fields).toEqual(['Location', 'Field', 'Subunit']);
    expect(ALIASES.fields).toEqual(['Alias', 'Location', 'Field', 'Subunit']);
    expect(INVALID.fields).toEqual([
      'Team',
      'Division',
      'Day',
      'Start',
      'End',
      'Length',
      'Location',
      'Field',
      'Subunit',
      'Valid From',
      'Valid Until',
      'Capacity',
      'Use',
      'Notes',
    ]);
  });

  it('shapes every cell of practice-schedule.csv (a team label may carry stray whitespace)', () => {
    for (const r of SCHEDULE.rows) {
      expect(r.Team).toMatch(/^( ?U\d\d[BG]-\d\d ?| ?)$/);
      expect(r.Division).toMatch(/^(U\d\d (Boys|Girls)|)$/);
      expect(r.Day).toMatch(/^(Mon|Tue|Wed|Thu|Fri)$/);
      expect(r.Start).toMatch(/^\d\d:\d\d$/);
      expect(r.End).toMatch(/^\d\d:\d\d$/);
      expect(r.Location).toMatch(/^(Venue [A-H]|Venue G Annex)$/);
      expect(r.Field).toMatch(/^(Field \d|Pitch [C-G]\d)$/);
      expect(r.Subunit).toMatch(/^([AB]|H1 North|H1 South)?$/);
      expect(r['Valid From']).toBe('');
      expect(r['Valid Until']).toBe('');
      expect(r.Capacity).toMatch(/^[12]?$/);
      expect(r.Use).toMatch(/^(hold)?$/);
      expect(r.Block).toMatch(/^(45|60)$/);
    }
  });

  it('shapes teams, divisions, surfaces and aliases', () => {
    for (const t of TEAMS.rows) {
      expect(t.Team).toMatch(/^U\d\d[BG]-\d\d$/);
      expect(t.Division).toMatch(/^U\d\d (Boys|Girls)$/);
      for (const c of [t['Coach 1'], t['Coach 2'], t['Coach 3']]) {
        expect(c).toMatch(/^(CoachFirst\d+ CoachLast\d+)?$/);
      }
    }
    for (const d of DIVISIONS.rows) {
      expect(d.Division).toMatch(/^U\d\d (Boys|Girls)$/);
      expect(d['Practices Per Week']).toBe('2');
      expect(d['Practice Minutes']).toMatch(/^(45|60)$/);
    }
    for (const s of SURFACES.rows) {
      expect(s.Location).toMatch(/^Venue [A-H]$/);
      expect(s.Field).toMatch(/^Field \d$/);
      expect(s.Subunit).toMatch(/^[AB]$/);
    }
    for (const a of ALIASES.rows) {
      expect(a.Alias).toMatch(/^(Pitch [C-G]\d|Venue G Annex|Annex Pitch|H1 North|H1 South)$/);
      expect(a.Location).toMatch(/^Venue [A-H]$/);
    }
  });

  it('holds no @ anywhere: no email, no phone, no free text', () => {
    for (const file of PRACTICE_FIXTURE_FILES) {
      expect(readFileSync(path.join(PRACTICE_FIXTURE_DIR, file), 'utf8')).not.toContain('@');
    }
  });

  it('holds 132 teams in 20 divisions, 19 coaches on two teams, and the ground the file uses', () => {
    expect(TEAMS.rows).toHaveLength(132);
    expect(DIVISIONS.rows).toHaveLength(20);
    expect(new Set(TEAMS.rows.map((t) => t.Division)).size).toBe(20);
    const shared = [...coachTeams(TEAMS.rows).values()].filter((t) => t.length === 2);
    expect(shared).toHaveLength(19);
    expect([...coachTeams(TEAMS.rows).values()].every((t) => t.length <= 2)).toBe(true);
    expect(SURFACES.rows).toHaveLength(58); // 29 fields, two halves each
  });
});

describe('practice fixture: the shape (counts only, near plan 4.11.1)', () => {
  const shape = shapeOf(SCHEDULE.rows);

  it('has the pinned produced shape', () => {
    for (const key of Object.keys(SHAPE)) expect([key, shape[key]]).toEqual([key, SHAPE[key]]);
    expect(shape.teamsWithRows).toBe(132); // the roster is whole: every team still has a row
  });

  it('lands near the targets of the plan', () => {
    const near = (actual, target, tolerance) =>
      expect(Math.abs(actual - target)).toBeLessThanOrEqual(tolerance);
    near(shape.placements, 235, 3);
    near(shape.placements45, 37, 2);
    near(shape.placements60, 198, 3);
    near(shape.rows, 726, 30); // 726 timed cells in the grid; a merged cell is one row here
    near(shape.wholeFieldPlacements, 20, 2);
    near(shape.sameSlotBothDays, 83, 2);
    near(shape.usedLabelledRows, 49, 2);
    expect(shape.venues).toBe(8);
    expect(shape.labelledRows).toBe(58);
  });

  it('keeps most of the rows open: capacity for a run to fill', () => {
    expect(shape.open).toBeGreaterThan(shape.placements * 1.5);
    expect(shape.open + shape.placements + shape.holds).toBe(shape.rows);
  });

  it('puts 45-minute practices on two weekdays only, and 60-minute ones on five', () => {
    const rows = SCHEDULE.rows.filter((r) => r.Team.trim() !== '');
    const days45 = new Set(rows.filter((r) => r.Block === '45').map((r) => r.Day));
    const days60 = new Set(rows.filter((r) => r.Block === '60').map((r) => r.Day));
    expect([...days45].sort()).toEqual(['Thu', 'Tue']);
    expect(days60.size).toBeGreaterThanOrEqual(4);
    const starts45 = new Set(SCHEDULE.rows.filter((r) => r.Block === '45').map((r) => r.Start));
    expect([...starts45].sort()).toEqual(['16:00', '16:45', '17:30']);
  });

  it('writes 17 fields, one venue and two halves in a spelling the alias file resolves', () => {
    const labels = new Set(
      SCHEDULE.rows
        .flatMap((r) => [r.Location, r.Field, r.Subunit])
        .filter((l) => /Pitch|Annex|North|South/.test(l))
    );
    expect(labels.size).toBe(17 + 1 + 2);
    const aliasKeys = new Set(ALIASES.rows.map((a) => a.Alias));
    expect([...labels].filter((l) => !aliasKeys.has(l))).toEqual([]);
    expect(ALIASES.rows).toHaveLength(21);
    const targets = new Set(
      ALIASES.rows.map((a) => JSON.stringify([a.Location, a.Field, a.Subunit]))
    );
    expect(targets.size).toBe(20);
  });
});

describe('practice fixture: the plants are counted from the CSV', () => {
  const counted = countPlants({
    rows: SCHEDULE.rows,
    teams: TEAMS.rows,
    divisions: DIVISIONS.rows,
  });

  it('finds each plant as many times as the generator planted it', () => {
    expect(counted.counts).toEqual(PRACTICE_PLANT_COUNTS);
    // the numbers the plan names (4.11.7)
    expect(PRACTICE_PLANT_COUNTS).toEqual({
      shortTeams: 29,
      doublePlaced: 5,
      coachClashes: 1,
      trailingWhitespace: 2,
      teamOnBothHalves: 1,
      overCapacity: 1,
      overlappingSlots: 1,
      holds: 1,
    });
  });

  it('agrees with the generator on WHICH teams, rows and coaches (not only how many)', () => {
    const planted = buildPracticeFixture().planted;
    // teams, coaches and row numbers are named the same way by both readings
    for (const kind of [
      'shortTeams',
      'doublePlaced',
      'teamOnBothHalves',
      'coachClashes',
      'trailingWhitespace',
      'holds',
    ]) {
      expect([kind, [...counted.who[kind]].sort()]).toEqual([kind, [...planted[kind]].sort()]);
    }
    // a cell or a pair of cells has no name both would spell alike: the count is compared
    for (const kind of ['overCapacity', 'overlappingSlots']) {
      expect([kind, planted[kind].length]).toEqual([kind, counted.who[kind].length]);
    }
  });

  it('finds nothing in the pre-plant copy, which is the control', () => {
    const clean = buildPracticeFixture({ plants: false });
    const control = countPlants({
      rows: parseCsv(clean.files['practice-schedule.csv']).rows,
      teams: parseCsv(clean.files['teams.csv']).rows,
      divisions: parseCsv(clean.files['divisions.csv']).rows,
    });
    expect(control.counts).toEqual(
      Object.fromEntries(Object.keys(counted.counts).map((k) => [k, 0]))
    );
    const shape = shapeOf(parseCsv(clean.files['practice-schedule.csv']).rows);
    expect(shape.placements).toBe(264); // 132 teams, two practices each
    expect(shape.singlePractice).toBe(0);
    expect(shape.wholeFieldPlacements).toBe(21); // 10 teams on both days, and one team's first day
    // the plan's other pre-plant facts: a clean control is not an empty file
    expect(shape.rows).toBeGreaterThan(600);
  });

  it('does not share the cells of two plants: each plant moved its own count', () => {
    // every plant's rows/teams are distinct from every other plant's (the generator tries
    // candidates until a plant moves only its own measure)
    const seen = new Map();
    for (const kind of ['doublePlaced', 'teamOnBothHalves', 'coachClashes']) {
      for (const who of counted.who[kind]) {
        expect([kind, who, seen.get(who)]).toEqual([kind, who, undefined]);
        seen.set(who, kind);
      }
    }
  });
});

describe('practice fixture: the sweep can see what it is asked to count', () => {
  const header = [
    'Team',
    'Division',
    'Day',
    'Start',
    'End',
    'Location',
    'Field',
    'Subunit',
    'Capacity',
    'Use',
  ];
  /** @param {string[][]} lines */
  const rowsOf = (lines) =>
    lines.map((cells) => Object.fromEntries(header.map((h, i) => [h, cells[i] ?? ''])));
  const teams = [
    { Team: 'T-1', Division: 'D', 'Coach 1': 'Coach X', 'Coach 2': '', 'Coach 3': '' },
    { Team: 'T-2', Division: 'D', 'Coach 1': 'Coach X', 'Coach 2': '', 'Coach 3': '' },
  ];
  const divisions = [{ Division: 'D', 'Practices Per Week': '2', 'Practice Minutes': '60' }];
  const count = (lines) => countPlants({ rows: rowsOf(lines), teams, divisions }).counts;
  const ZERO = {
    shortTeams: 0,
    doublePlaced: 0,
    coachClashes: 0,
    trailingWhitespace: 0,
    teamOnBothHalves: 0,
    overCapacity: 0,
    overlappingSlots: 0,
    holds: 0,
  };
  // a clean file: each team twice, different weekdays, nothing shared
  const clean = [
    ['T-1', 'D', 'Mon', '16:00', '17:00', 'V', 'F1', 'A', '', ''],
    ['T-1', 'D', 'Wed', '16:00', '17:00', 'V', 'F1', 'A', '', ''],
    ['T-2', 'D', 'Tue', '17:00', '18:00', 'V', 'F1', 'B', '', ''],
    ['T-2', 'D', 'Thu', '17:00', '18:00', 'V', 'F1', 'B', '', ''],
  ];

  it('counts nothing on a clean file', () => {
    expect(count(clean)).toEqual(ZERO);
  });

  it('counts each defect once, and only its own measure', () => {
    // short: T-2 loses a row
    expect(count(clean.slice(0, 3))).toEqual({ ...ZERO, shortTeams: 1 });
    // double-placed: T-1's Wednesday row moves to Monday at 16:00 on another field
    const doubled = clean.map((r, i) =>
      i === 1 ? ['T-1', 'D', 'Mon', '16:00', '17:00', 'V', 'F2', 'A', '', ''] : r
    );
    expect(count(doubled)).toEqual({ ...ZERO, doublePlaced: 1 });
    // on both halves: the same, on the other half of the same field
    const halves = clean.map((r, i) =>
      i === 1 ? ['T-1', 'D', 'Mon', '16:00', '17:00', 'V', 'F1', 'B', '', ''] : r
    );
    expect(count(halves)).toEqual({ ...ZERO, teamOnBothHalves: 1 });
    // coach clash: T-2's Tuesday row moves to Monday 16:30, on another field (the coach has both teams)
    const clash = clean.map((r, i) =>
      i === 2 ? ['T-2', 'D', 'Mon', '16:30', '17:30', 'V', 'F2', 'A', '', ''] : r
    );
    expect(count(clash)).toEqual({ ...ZERO, coachClashes: 1 });
    // trailing whitespace
    expect(count(clean.map((r, i) => (i === 0 ? ['T-1 ', ...r.slice(1)] : r)))).toEqual({
      ...ZERO,
      trailingWhitespace: 1,
    });
    // a hold
    expect(
      count([...clean, ['', '', 'Fri', '16:00', '17:00', 'V', 'F1', 'A', '', 'hold']])
    ).toEqual({
      ...ZERO,
      holds: 1,
    });
    // over capacity: two teams in one capacity-1 cell; with capacity 2 it is not
    const shared = clean.map((r, i) =>
      i === 2 ? ['T-2', 'D', 'Mon', '16:00', '17:00', 'V', 'F1', 'A', '', ''] : r
    );
    expect(count(shared)).toMatchObject({ overCapacity: 1 });
    const roomy = shared.map((r) => (r[2] === 'Mon' ? [...r.slice(0, 8), '2', ''] : r));
    expect(count(roomy).overCapacity).toBe(0);
  });

  it('counts an overlap only on one ground: halves apart and back to back are not overlaps', () => {
    const open = (sub, start, end) => ['', '', 'Fri', start, end, 'V', 'F1', sub, '', ''];
    // whole field against a half overlaps; two different halves do not; back to back does not
    expect(
      count([...clean, open('', '16:00', '17:00'), open('A', '16:30', '17:30')])
    ).toMatchObject({ overlappingSlots: 1 });
    expect(
      count([...clean, open('A', '16:00', '17:00'), open('B', '16:00', '17:00')]).overlappingSlots
    ).toBe(0);
    expect(
      count([...clean, open('A', '16:00', '17:00'), open('A', '17:00', '18:00')]).overlappingSlots
    ).toBe(0);
  });
});

describe('practice fixture: practice-invalid.csv', () => {
  /** The closed lists of plan 4.11.4, written out here rather than imported. */
  const ROW_REASONS = [
    'bad-use',
    'bad-day',
    'bad-time',
    'bad-length',
    'end-not-after-start',
    'bad-capacity',
    'capacity-not-positive',
    'bad-date',
    'valid-until-before-from',
    'outside-season-window',
    'missing-dates',
    'unknown-division',
    'unknown-team',
    'unknown-location',
    'unknown-field',
    'unknown-subunit',
    'team-in-two-divisions',
    'slot-overlaps-another',
    'duplicate-row',
  ];
  const ACCEPTED = [
    'ok',
    'open',
    'hold',
    'team-on-both-halves',
    'hold-over-open-slot',
    'division-not-reserved',
  ];
  const expectations = INVALID.rows.map((r) => r.Notes.replace(/^expect: /, ''));

  it('has about twenty to thirty rows and one for every row-level refusal reason', () => {
    expect(INVALID.rows.length).toBeGreaterThanOrEqual(24);
    expect(INVALID.rows.length).toBeLessThanOrEqual(40);
    for (const reason of ROW_REASONS) expect(expectations).toContain(reason);
  });

  it('also carries the accepted rows: a control, an open slot, a hold, the flags', () => {
    for (const kind of ACCEPTED) expect(expectations).toContain(kind);
    for (const e of expectations) expect([...ROW_REASONS, ...ACCEPTED]).toContain(e.split(' ')[0]);
    for (const r of INVALID.rows) expect(r.Notes).toMatch(/^expect: [a-z-]+$/);
  });

  it('uses the US date form and the 12-hour time form in rows that are valid', () => {
    const valid = INVALID.rows.filter((r) => r.Notes === 'expect: ok');
    expect(valid.some((r) => /^\d{1,2}\/\d{1,2}\/\d{4}$/.test(r['Valid From']))).toBe(true);
    expect(valid.some((r) => /^\d{1,2}:\d{2} [AP]M$/i.test(r.Start))).toBe(true);
    expect(valid.some((r) => /^12:\d\d [AP]M$/i.test(r.Start))).toBe(true);
    expect(valid.some((r) => /^(Monday|Tuesday|tue|WED)$/.test(r.Day))).toBe(true);
    // and the swapped-day-and-month case the parser must not "repair"
    expect(
      INVALID.rows.some((r) => r['Valid From'] === '13/04/2026' && r.Notes === 'expect: bad-date')
    ).toBe(true);
  });

  it('reads its season with a start date and no end date: that is how missing-dates is reachable', () => {
    // every row that is not about dates carries both of its own dates; the one row without a
    // Valid Until is the missing-dates row, and the one without a Valid From falls back to the start.
    const without = INVALID.rows.filter((r) => r['Valid Until'] === '');
    expect(without.map((r) => r.Notes)).toContain('expect: missing-dates');
  });
});
